alter table public.sales_log_rows add column if not exists row_key text, add column if not exists last_seen_at timestamptz, add column if not exists removed_at timestamptz, add column if not exists phone text, add column if not exists city text, add column if not exists cancelled boolean not null default false; alter table public.completion_log_rows add column if not exists row_key text, add column if not exists last_seen_at timestamptz, add column if not exists removed_at timestamptz; create or replace function public.sheet_row_key(p_name text, p_pid text, p_date date) returns text language sql immutable as $fn$ select public.norm_person(p_name) || '|' || coalesce(p_pid, '') || '|' || coalesce(p_date::text, '') $fn$; create or replace function public.clog_row_key(p_name text, p_addr text, p_contract numeric) returns text language sql stable as $fn$ select public.norm_person(p_name) || '|' || coalesce(public.address_key(p_addr), '') || '|' || coalesce(round(p_contract, 2)::text, '') $fn$; create table if not exists public.sheet_sync_runs (id bigint generated always as identity primary key, received_at timestamptz not null default now(), reason text, summary jsonb, ok boolean, error text); alter table public.sheet_sync_runs enable row level security; create policy sheet_sync_runs_admin_read on public.sheet_sync_runs for select using (public.is_admin()); create table if not exists public.sheet_sync_issues (id bigint generated always as identity primary key, kind text not null, sheet_ref text not null, job_id uuid references public.jobs(id) on delete cascade, sheet_value numeric, td_value numeric, detail text, first_seen timestamptz not null default now(), last_seen timestamptz not null default now(), resolved_at timestamptz, unique (kind, sheet_ref)); alter table public.sheet_sync_issues enable row level security; create policy sheet_sync_issues_admin_read on public.sheet_sync_issues for select using (public.is_admin()); comment on table public.sheet_sync_issues is 'Things the Google Sheet sync found but did not change: contract amounts that differ from the Sales tab, Sales rows that disappeared, Hold names it could not match. Resolved automatically when they line up again.';;
